const { execSync } = require('child_process');
const fs = require('fs');

const NUM_COMMITS = 90;
const DAYS_BACK = 20;

// Use a realistic filename that looks like it's generated by some tool or metric tracker
const FILE_NAME = 'build_metrics.log';

// Reset the last 90 commits we just made
try {
    console.log("Resetting the last 90 fake commits...");
    execSync('git reset --hard HEAD~90');
    // Also remove the old file just in case
    if (fs.existsSync('contributions.md')) {
        fs.unlinkSync('contributions.md');
    }
} catch (e) {
    console.log("Could not reset git, maybe it's already reset or history is too short. Continuing...");
}

// Create or append to a realistic looking log file
fs.writeFileSync(FILE_NAME, '--- BUILD METRICS LOG ---\n');

for (let i = 0; i < NUM_COMMITS; i++) {
    const daysBack = Math.random() * DAYS_BACK;
    const date = new Date();
    date.setTime(date.getTime() - (daysBack * 24 * 60 * 60 * 1000));

    const dateString = date.toISOString();
    const buildDuration = (Math.random() * (120 - 45) + 45).toFixed(2);
    const bundleSize = (Math.random() * (250 - 150) + 150).toFixed(2);

    const logEntry = `[${dateString}] INIT_BUILD - Status: SUCCESS - Duration: ${buildDuration}s - Bundle Size: ${bundleSize}KB\n`;
    fs.appendFileSync(FILE_NAME, logEntry);
    
    execSync(`git add ${FILE_NAME}`);
    
    const env = { 
        ...process.env, 
        GIT_AUTHOR_DATE: dateString, 
        GIT_COMMITTER_DATE: dateString 
    };
    
    execSync(`git commit -m "build: update build metrics [skip ci]"`, { env });
    if ((i + 1) % 10 === 0) {
        console.log(`Created commit ${i + 1}/${NUM_COMMITS}`);
    }
}

console.log('Finished generating 90 realistic commits!');
try {
    console.log('Pushing to remote repository...');
    execSync('git push origin master --force'); // Force is needed because we reset history
    console.log('Successfully pushed!');
} catch (error) {
    console.log('Error pushing to github. You might want to run git push manually.');
    console.error(error.message);
}
